const { ThermalPrinter, PrinterTypes, CharacterSet, BreakLine } = require('../node-thermal-printer');

async function example(interface) {
  const printer = new ThermalPrinter({
    type: PrinterTypes.EPSON, // 'star' or 'epson'
    interface,
    options: {
      timeout: 1000,
    },
    width: 48, // Number of characters in one line - default: 48
  });

  const commands = [];

  // Initialize printer
  commands.push(0x1B, 0x40);

  // Select page mode
  commands.push(0x1B, 0x4C);

  // Turn 90deg clockwise rotation mode on/off
  commands.push(0x1B, 0x56, 25);

  // Set printing area in page mode (14cm x 7cm at 203 DPI)
  const width = 200;
  const height = 200;
  commands.push(
    0x1B, 0x57,
    0x00, 0x00,  // x = 0
    0x00, 0x00,  // y = 0
    width & 0xFF, (width >> 8) & 0xFF,
    height & 0xFF, (height >> 8) & 0xFF
  );

  // Set position (2cm, 1cm)
  const x = 0x00;  // ~2cm
  const y = 0x00;   // ~1cm
  commands.push(
    0x1B, 0x24,
    // x & 0xFF, (x >> 8) & 0xFF,
    // y & 0xFF, (y >> 8) & 0xFF
    x, y
  );
  // Add text
  commands.push(...Buffer.from('Hello Label! this is a text'));

  // Print page
  commands.push(0x0C);

  // Select standard mode
  commands.push(0x1B, 0x53);

  // Select cut mode and cut paper
  commands.push(0x1D, 0x56, 0x00);

  console.log(Buffer.from(commands))

  printer.append(Buffer.from(commands));

  console.log(printer.getText());

  try {
    await printer.execute();
    console.log('Print success.');
  } catch (error) {
    console.error('Print error:', error);
  }
}

async function main() {
  await example('tcp://192.168.100.87:9100');

}
main();